(()=>{'use strict';const U='https://gfggmkeucgqkkyvummpu.supabase.co',K='sb_publishable_ptCVbq9h15prKhT0OO5Zmg_LkE3cbK0';const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));async function api(path){const r=await fetch(U+path,{headers:{apikey:K,Authorization:`Bearer ${K}`,Accept:'application/json'}});if(!r.ok)throw Error(`HTTP ${r.status}`);return r.json()}const icon=c=>({'Infrastruktur':'🛣️','Kesehatan':'🏥','Pendidikan':'🎓','Lingkungan':'🌱','Ekonomi':'📈','Sosial':'👥','Kemiskinan':'🏠','Transportasi':'🚌','Pertanian':'🌾','Bencana':'🌧️','Air Bersih':'💧'}[c]||'◉');const known=['Pendidikan','Kesehatan','Infrastruktur','Ekonomi','Sosial','Lingkungan','Kemiskinan','Pertanian','Bencana','Air Bersih','Transportasi'];function home(){const host=document.getElementById('home');if(!host)return;host.innerHTML=`<div class="clean-home"><section class="clean-hero"><div class="clean-hero-copy"><span class="clean-eyebrow">WASKITA · PORTAL DATA & ASPIRASI PUBLIK</span><h1>Kenali masalah.<br><strong>Pahami dampaknya.</strong></h1><p>Temukan informasi publik berdasarkan bidang, lihat perkembangan, dan sampaikan suara Anda dengan nyaman.</p><form class="clean-search" id="cleanSearch"><span>⌕</span><input id="cleanQuestion" placeholder="Cari masalah, bidang, atau wilayah…"><button type="submit">Cari</button></form><div class="hero-actions"><button data-view="problems" class="clean-primary">Jelajahi Masalah →</button><button data-view="report" class="clean-ghost">Suara Warga</button></div></div><div class="clean-garuda" role="img" aria-label="Garuda IKN"></div></section><section class="clean-section field-intro"><div class="clean-section-head"><div><span>BIDANG PUBLIK</span><h2>Masalah Indonesia berdasarkan bidang</h2><p>Pilih bidang yang ingin Anda pahami. Wilayah dan detail masalah tersedia di menu Peta Indonesia dan Masalah.</p></div></div><div class="clean-field-grid" id="homeCategories">${known.map(k=>`<button data-view="problems"><i>${icon(k)}</i><span><b>${k}</b><small>Jelajahi masalah</small></span><em>→</em></button>`).join('')}</div></section><section class="clean-feature"><article class="clean-panel clean-map-card"><div class="clean-panel-head"><div><span>PETA & WILAYAH</span><h2>Telusuri berdasarkan wilayah</h2><p>Gunakan Peta Indonesia untuk masuk dari provinsi hingga desa/kelurahan.</p></div><button data-view="map" class="clean-link">Buka peta →</button></div><div class="clean-map-placeholder"><div id="homeIndonesiaMap" class="clean-map-real"></div><div class="clean-map-caption">Peta wilayah · klik provinsi untuk mulai menelusuri</div></div></article><article class="clean-panel clean-report-card"><div class="visual-badge">📣</div><span>SUARA WARGA</span><h2>Sampaikan laporan dengan mudah</h2><p>Tambahkan kronologi, lokasi, foto, dan video. Laporan warga dipisahkan dari data yang telah diverifikasi.</p><button data-view="report" class="clean-primary">Buat Laporan Warga →</button><div class="report-steps"><span>01 Kirim</span><span>02 Verifikasi</span><span>03 Pantau</span></div></article></section><section class="clean-section"><div class="clean-section-head"><div><span>TERKINI</span><h2>Masalah yang baru diperbarui</h2><p>Informasi yang tersedia untuk publik.</p></div><button data-view="problems" class="clean-link">Lihat semua →</button></div><div class="clean-issues" id="homeIssues"><div class="clean-loading">Memuat data…</div></div></section><section class="clean-section clean-premium-info"><div class="premium-card"><div class="premium-icon">◎</div><div><span>WASKITA</span><h2>Satu ruang publik untuk melihat, memahami, dan mengantisipasi.</h2><p>Data, masalah, wilayah, suara warga, dan perubahan disajikan dalam alur yang sederhana dan dapat ditelusuri.</p></div><div class="info-actions"><button data-view="data" class="clean-primary">Buka Data & Statistik</button><button data-view="monitoring" class="clean-ghost-dark">Pantau Perubahan</button></div></div></section></div>`;wire();loadHomeData();document.getElementById('cleanSearch')?.addEventListener('submit',e=>{e.preventDefault();const q=document.getElementById('cleanQuestion')?.value.trim();if(q)window.render?.('result',q)})}function wire(){document.querySelectorAll('#home [data-view]').forEach(b=>b.onclick=()=>window.render?.(b.dataset.view));try{window.lucide?.createIcons()}catch{}}async function loadHomeData(){try{const problems=await api('/rest/v1/problems?select=id,title,category,status,updated_at,region_id&order=updated_at.desc&limit=100');const issues=document.getElementById('homeIssues');issues.innerHTML=problems.slice(0,6).map(x=>`<button class="clean-issue" data-problem="${esc(x.id)}"><i>${icon(x.category)}</i><div><b>${esc(x.title||'Masalah tanpa judul')}</b><span>${esc(x.category||'Masalah')} · ${esc(x.status||'tercatat')} · ${x.updated_at?new Date(x.updated_at).toLocaleDateString('id-ID'):''}</span></div><em>Detail →</em></button>`).join('')||'<div class="clean-empty">Belum ada masalah publik yang tersedia.</div>';issues.querySelectorAll('[data-problem]').forEach(b=>b.onclick=()=>window.render?.('problem-detail',b.dataset.problem));}catch(e){document.getElementById('homeIssues')?.replaceChildren(Object.assign(document.createElement('div'),{className:'clean-empty',textContent:'Data masalah belum dapat dimuat. Silakan coba lagi.'}))}}const previousRender=window.render;window.render=async function(v,x=''){if(v==='home'){home();window.scrollTo({top:0,behavior:'smooth'});return}if(typeof previousRender==='function')return previousRender(v,x)};document.addEventListener('DOMContentLoaded',home)})();